import sys

class InputReader:
    def __init__(self, stream):
        self.reader = stream
        self.tokens = []
        self.index = 0

    def next(self):
        while self.index >= len(self.tokens):
            line = self.reader.readline()
            if not line:
                raise RuntimeError("No more input")
            self.tokens = line.strip().split()
            self.index = 0
        token = self.tokens[self.index]
        self.index += 1
        return token

    def NextInt(self):
        return int(self.next())

    def NextLong(self):
        return int(self.next())

class GTakeMetro:
    def __init__(self):
        self.n = 0
        self.m = 0
        self.s = 0
        self.t = 0

    def step(self):
        curJump = int(self.t % self.n)
        sign = 1 if self.s < self.m else -1
        self.s += sign * curJump
        self.s %= self.n

    def doLoop(self):
        for _ in range(self.n):
            self.step()

    def solve(self, testNumber, in_stream, out_stream):
        self.n = in_stream.NextInt()
        self.m = in_stream.NextInt()
        self.s = in_stream.NextInt() - 1
        self.t = in_stream.NextLong()

        while (self.t % self.n) != 0:
            self.step()

        lastSeem = [-1] * self.n
        while self.t != 0:
            self.doLoop()
            if lastSeem[self.s] != -1:
                interval = lastSeem[self.s] - self.t
                self.t %= interval
                break
            else:
                lastSeem[self.s] = self.t

        while self.t != 0:
            self.step()
        out_stream.write(str(self.s + 1) + "\n")

def main():
    in_stream = InputReader(sys.stdin)
    out_stream = sys.stdout
    solver = GTakeMetro()
    solver.solve(1, in_stream, out_stream)

if __name__ == "__main__":
    main()
